void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Define PI
    const float PI = 3.14159265359;

    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Center the UV coordinates
    uv = uv - 0.5;

    // Calculate the distance from the center
    float dist = length(uv);

    // Create a vignette effect based on distance
    float vignette = 1.0 - smoothstep(0.2, 0.5, dist);

    // Calculate an angle based on the UV coordinates
    float angle = atan(uv.y, uv.x);

    // Map the angle to a 0-1 range
    float hue = (angle / (2.0 * PI)) + 0.5;

    // Create a rainbow color using HSV to RGB conversion
    vec3 col;
    col.r = abs(hue * 6.0 - 3.0) - 1.0;
    col.g = 2.0 - abs(hue * 6.0 - 2.0);
    col.b = 2.0 - abs(hue * 6.0 - 4.0);
    col = clamp(col, 0.0, 1.0);

    // Apply the vignette
    col *= vignette;

    // Output to screen
    fragColor = vec4(col,1.0);
}
